python3 -c "
import json,glob
RES={'done','dropped','blocked'}
omitted_shape=0; explicit_shape=0; rows=[]
tot_plans=0; plans_with_omission=0
for path in sorted(glob.glob('.sofar/initiatives/*/events.jsonl')):
    slug=path.split('/')[2]
    evs=[]
    for l in open(path):
        l=l.strip()
        if l:
            try: evs.append(json.loads(l))
            except: pass
    evs.sort(key=lambda e: e.get('id',''))
    phases={}; tasks={}
    for e in evs:
        t,p=e.get('type'),e.get('payload',{})
        if t=='plan_updated':
            tot_plans+=1
            pl=p.get('plan',{}).get('phases',[])
            omits = any('status' not in ph for ph in pl) or any('status' not in tk for ph in pl for tk in ph.get('tasks',[]))
            if omits: plans_with_omission+=1
            new_ph={ph['name']:ph.get('status','pending') for ph in pl}
            new_tk={tk['id']:tk.get('status','pending') for ph in pl for tk in ph.get('tasks',[])}
            for n,old in phases.items():
                if old in RES and new_ph.get(n,'pending')!=old and new_ph.get(n,'pending') not in RES:
                    (rows.append((slug,e['ts'][:16],'phase',n,old,new_ph.get(n,'<ABSENT>'),omits)))
            for i,old in tasks.items():
                if old in RES and new_tk.get(i,'pending')!=old and new_tk.get(i,'pending') not in RES:
                    rows.append((slug,e['ts'][:16],'task',i,old,new_tk.get(i,'<ABSENT>'),omits))
            phases,tasks=new_ph,new_tk
        elif t=='phase_status_changed': phases[p['phase']]=p['status']
        elif t=='task_status_changed': tasks[p['id']]=p['status']
        elif t=='task_added': tasks[p['id']]=p.get('status','pending')
print('plan_updated events total:',tot_plans,'| with any omitted status:',plans_with_omission)
print('resolved entries displaced at a replan:',len(rows))
from collections import Counter
print('  in a payload that OMITS somewhere:',sum(1 for r in rows if r[6]))
print('  in a fully-explicit payload:      ',sum(1 for r in rows if not r[6]))
print('  landing value:',Counter(r[5] for r in rows))
"

